class Solution {
public:
    int countMaxOrSubsets(vector<int>& nums){int n=nums.size(),target=0,ans=0;
        for(int x:nums)target|=x;
        for(int mask=1;mask<(1<<n);++mask){int v=0;
            for(int i=0;i<n;++i)if(mask>>i&1)v|=nums[i];
            if(v==target)++ans;
        }
        return ans;
    }
};
